  let pg='';const btn=(i,l)=>'<button data-p="'+i+'"'+(i===p?' class="on"':'')+'>'+l+'</button>';if(pages>1){if(p>0)pg+=btn(p-1,'‹');for(let i=Math.max(0,p-2);i<Math.min(pages,p+3);i++)pg+=btn(i,i+1);if(p<pages-1)pg+=btn(p+1,'›')}
